import path from "node:path";
import { fileURLToPath } from "node:url";
import { defineConfig, devices } from "@playwright/test";

const __dirname = path.dirname(fileURLToPath(import.meta.url));

/**
 * Real-browser tests of the Receipt Designer and Generated Receipts against the PRODUCTION build (dist/), served the way the nginx
 * image serves it (e2e/serve-dist.mjs). The real pdf.js renders genuine PDFs generated by the backend's receipt renderer; only the
 * JSON/PDF API responses are stubbed, so no backend or database is needed.
 *
 *   npm run build && npx playwright test -c playwright.receipts.config.ts
 *
 * Set PW_CHANNEL=chrome to use an installed Google Chrome instead of Playwright's Chromium.
 */
export default defineConfig({
  testDir: "./e2e",
  testMatch: /(receipts?|courses?)-.*\.spec\.ts/,
  fullyParallel: false,
  workers: 1,
  retries: 0,
  timeout: 30_000,
  reporter: [["list"]],
  use: { baseURL: process.env.E2E_BASE_URL ?? "http://127.0.0.1:4173", trace: "retain-on-failure", screenshot: "only-on-failure" },
  projects: [{ name: "chromium", use: { ...devices["Desktop Chrome"], channel: process.env.PW_CHANNEL || undefined } }],
  // E2E_BASE_URL points the tests at an already running server (for example the real nginx image) instead of the built-in static server
  webServer: process.env.E2E_BASE_URL ? undefined : { command: "node e2e/serve-dist.mjs 4173", cwd: __dirname, url: "http://127.0.0.1:4173", reuseExistingServer: false, timeout: 30_000 },
});
